'use strict';
// Discussion prototype: browser-only sample state; no IPC, real accounts, audio or music file access.
const paths = {
 home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z',
 search:'m21 21-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',
 songs:'M9 18V5l12-2v13M9 8l12-2M9 18a3 3 0 1 1-3-3h3m12 1a3 3 0 1 1-3-3h3',
 albums:'M3 3h18v18H3ZM16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0',
 artists:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0M4 21v-2a8 8 0 0 1 16 0v2',
 download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',
 playlist:'M4 5h16M4 10h16M4 15h9M4 20h9m5-5 4 3-4 3Z',
 online:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0M3 12h18M12 3a17 17 0 0 1 0 18 17 17 0 0 1 0-18',
 offline:'m3 3 18 18M5 8a13 13 0 0 0-3 2m7-4a13 13 0 0 1 13 4M5 14a9 9 0 0 1 3-2m4 0a9 9 0 0 1 7 2m-11 4a5 5 0 0 1 8 0m-4 3h.01',
 play:'m8 4 12 8-12 8Z', pause:'M8 4v16M16 4v16', next:'m5 4 11 8L5 20ZM20 4v16', previous:'m19 4-11 8 11 8ZM4 4v16',
 volume:'M11 4 5 9H2v6h3l6 5ZM15 8a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14',
 plus:'M12 4v16M4 12h16', queue:'M4 5h16M4 10h16M4 15h11M4 20h11m4-5 4 3-4 3Z',
 more:'M5 12h.01M12 12h.01M19 12h.01', check:'m5 12 4 4L19 6', folder:'M3 6h7l2 2h9v12H3Z', close:'m6 6 12 12M6 18 18 6', gear:'M12 8a4 4 0 1 1 0 8 4 4 0 0 1 0-8M12 2v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2', arrow:'m9 5 7 7-7 7', shuffle:'m3 5 18 14m-5 0h5v-5M3 19l7-7m4-4 7-3m-5 0h5v5', repeat:'m17 2 4 4-4 4M3 11V8a2 2 0 0 1 2-2h16M7 22l-4-4 4-4m14-1v3a2 2 0 0 1-2 2H3',
};
const icon = (name) => `<svg class="icon" aria-hidden="true" viewBox="0 0 24 24"><path d="${paths[name] || paths.songs}"/></svg>`;
const esc = (v) => String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const STORAGE = 'alger-music-wireframe-v2';
const initialSongs = [
 {id:1,title:'日光之间',artist:'林间来信',album:'慢慢醒来',duration:'4:12',local:true,origin:'manual',cover:'I'},
 {id:2,title:'夜航',artist:'北岸乐队',album:'城市另一面',duration:'3:46',local:true,origin:'manual',cover:'II'},
 {id:3,title:'Blue Hour',artist:'The Quiet Room',album:'After Hours',duration:'5:08',local:true,origin:'auto',cover:'III'},
 {id:4,title:'四月的风',artist:'远山',album:'春日手记',duration:'3:52',local:false,cover:'IV'},
 {id:5,title:'一封没有寄出的信',artist:'林间来信',album:'慢慢醒来',duration:'4:31',local:true,origin:'manual',cover:'I'},
 {id:6,title:'雨落时',artist:'周野',album:'独奏',duration:'2:58',local:false,cover:'V'},
 {id:7,title:'Coastline',artist:'The Quiet Room',album:'After Hours',duration:'4:20',local:false,cover:'III'},
 {id:8,title:'归途',artist:'北岸乐队',album:'城市另一面',duration:'3:39',local:true,origin:'auto',cover:'II'},
 {id:9,title:'下一站晴天',artist:'林间来信',album:'沿途',duration:'4:02',local:false,cover:'VI',fresh:true},
 {id:10,title:'城市微光',artist:'北岸乐队',album:'微光',duration:'3:41',local:false,cover:'VII',fresh:true},
 {id:11,title:'Still Here',artist:'The Quiet Room',album:'Small Hours',duration:'4:16',local:false,cover:'VIII',fresh:true},
 {id:12,title:'山海之间',artist:'远山',album:'回声',duration:'3:38',local:false,cover:'IX',fresh:true},
];
const initialPlaylists = [
 {id:'morning',name:'慢慢醒来',scope:'local',description:'留给清晨的音乐',ids:[1,2,8]},
 {id:'quiet',name:'安静片刻',scope:'local',description:'慢下来，听一会儿',ids:[3,5]},
 {id:'favorites',name:'我喜欢的音乐',scope:'remote',description:'网易云音乐 · 我的收藏',ids:[1,4,7,10]},
 {id:'cloud-night',name:'夜间漫游',scope:'remote',description:'网易云音乐 · 我创建的歌单',ids:[2,3,6,11]},
];
let saved;
try { saved = JSON.parse(localStorage.getItem(STORAGE) || 'null'); } catch { saved = null; }
const songs = structuredClone(initialSongs).map((s,i)=>({...s,filePath:`../${s.artist} - ${s.title}.flac`,addedAt:i,listenCount:0,...saved?.songs?.find(t=>t.id===s.id)}));
const playlists = saved?.playlists || structuredClone(initialPlaylists);
const state = {
 route:'home', query:'', offline:false, loggedIn:true, accountOpen:false, queueOpen:false,
 current:1, playing:false, playbackSource:'local', progress:0, volume:70, run:0, countedRun:-1, seeked:false,
 queue:[1,2,8], activePlaylist:'morning', queueTitle:'慢慢醒来', fmSeed:'favorites',
 shuffle:false, repeat:false, editing:false, addIntent:null, metadataCandidate:null,
 settings:{autoSave:true,threshold:3,showRemote:true,localExpanded:true,remoteExpanded:true,...saved?.settings},
 downloads:(saved?.pendingDownloads || []).map(t=>({...t,status:t.status==='failed'?'failed':'running'})),
};
const song = id => songs.find(s=>s.id===Number(id));
const playlist = id => playlists.find(p=>p.id===id);
const playable = s => Boolean(s && (s.local || !state.offline));
const sourceTag = s => `<span class="tag ${s.local?'local':''}">${s.local?'本地':'网络'}</span>`;
const button = (label,action,attrs='',cls='') => `<button class="${cls}" data-action="${action}" ${attrs}>${label}</button>`;
function persist(){
 try { localStorage.setItem(STORAGE,JSON.stringify({songs,playlists,settings:state.settings,pendingDownloads:state.downloads.filter(t=>t.status!=='done')})); } catch { /* The preview also works without browser storage. */ }
}
function notify(message){const e=document.querySelector('#notice');e.textContent=message;e.classList.add('visible');clearTimeout(notify.timer);notify.timer=setTimeout(()=>e.classList.remove('visible'),3600);}
function heading(name,subtitle='',actions='',eyebrow=''){return `${eyebrow?`<div class="eyebrow">${esc(eyebrow)}</div>`:''}<div class="heading"><div><h1>${esc(name)}</h1>${subtitle?`<p class="subtitle">${subtitle}</p>`:''}</div><div class="page-actions">${actions}</div></div>`;}
function title(){if(state.query.trim())return '搜索';const p=playlist(state.route.slice(9));return ({home:'首页',songs:'歌曲',albums:'专辑',artists:'艺人',downloads:downloadTitle(),settings:'设置'})[state.route] || (state.route.startsWith('artist:')?state.route.slice(7):state.route.startsWith('album:')?state.route.slice(6):p?.name || 'Alger Music');}
function navigate(route){state.route=route;state.query='';state.editing=false;state.accountOpen=false;shell();}
function nav(route,label,name,count=''){return `<button class="nav-item ${state.route===route&&!state.query?'active':''}" data-route="${esc(route)}" ${state.route===route&&!state.query?'aria-current="page"':''}>${icon(name)}<span>${esc(label)}</span>${count!==''?`<small>${count}</small>`:''}</button>`;}
function downloadTitle(){return state.downloads.some(t=>t.status==='running'||t.status==='paused')?'正在下载':state.downloads.some(t=>t.status==='failed')?'下载待处理':'已下载';}
function playlistGroup(scope){const local=scope==='local';const expanded=state.settings[local?'localExpanded':'remoteExpanded'];const list=playlists.filter(p=>p.scope===scope);return `<section class="playlist-group"><details data-group="${scope}" ${expanded?'open':''}><summary>${local?'本地歌单':'远程歌单'}</summary>${list.map(p=>nav(`playlist:${p.id}`,p.name,'playlist')).join('')}${!list.length?'<p class="group-empty">还没有歌单</p>':''}</details>${button(icon('plus'),'create-playlist',`data-scope="${scope}" aria-label="新建${local?'本地':'远程'}歌单" ${!local&&(!state.loggedIn||state.offline)?'disabled':''}`,'group-create icon-button')}</section>`;}
function accountMenu(){return `<div class="account-menu" role="group" aria-label="用户菜单"><strong>${state.loggedIn?'示例用户':'尚未登录'}</strong><p>${state.loggedIn?'网易云音乐 · 示例账号':'登录后同步头像、用户名和远程歌单'}</p>${button(state.loggedIn?'退出示例账号':'连接网易云账号','login',state.offline?'disabled':'')}${button('设置…','settings')}${button('关闭','account-close')}</div>`;}
function shell(){
 const focused=document.activeElement?.id;const previous=document.activeElement;const selection=previous instanceof HTMLInputElement&&previous.type==='search'?[previous.selectionStart,previous.selectionEnd]:null;
 if(state.route==='downloads'&&!state.downloads.length)state.route='songs';
 document.querySelector('#app').innerHTML=`<aside class="sidebar"><div class="traffic" aria-hidden="true"><i></i><i></i><i></i></div><nav aria-label="主导航">${nav('home','首页','home')}<div class="nav-section">资料库</div>${nav('songs','歌曲','songs')}${nav('albums','专辑','albums')}${nav('artists','艺人','artists')}${state.downloads.length?nav('downloads',downloadTitle(),'download',state.downloads.filter(t=>t.status!=='done').length||state.downloads.length):''}${playlistGroup('local')}${state.settings.showRemote&&state.loggedIn?`<hr class="group-divider">${playlistGroup('remote')}`:''}</nav><div class="sidebar-foot">${state.accountOpen?accountMenu():''}<button class="account-button" data-action="account" aria-expanded="${state.accountOpen}"><span class="avatar">${icon('artists')}</span><span><strong>${state.loggedIn?'示例用户':'登录网易云'}</strong><small>${state.loggedIn?'网易云音乐':'本地音乐可直接使用'}</small></span>${icon('more')}</button></div></aside><header class="toolbar"><label class="search">${icon('search')}<input id="global-search" type="search" value="${esc(state.query)}" placeholder="搜索本地与网络音乐" aria-label="搜索本地与网络音乐"></label></header><div class="workspace"><main class="content" id="content"></main>${state.queueOpen?queueView():''}</div><footer class="player" id="player"></footer>`;
 renderContent();renderPlayer();updateSimulation();
 if(focused){const replacement=document.getElementById(focused);if(replacement&&replacement!==previous){replacement.focus({preventScroll:true});if(selection)replacement.setSelectionRange(...selection);}}
 document.querySelectorAll('details[data-group]').forEach(e=>e.addEventListener('toggle',()=>{state.settings[e.dataset.group==='local'?'localExpanded':'remoteExpanded']=e.open;persist();}));
}
function offlineBanner(){return state.offline?`<div class="notice-banner">${icon('offline')}<span>当前离线。本地音乐照常播放，网络内容恢复联网后可用。</span></div>`:'';}
function table(list,{source=false,context=null,library=false}={}){
 if(!list.length)return '<div class="empty compact"><h2>这里还没有歌曲</h2><p>使用上方搜索寻找音乐，再加入歌单或保存到本地。</p></div>';
 return `<div class="table-wrap"><table><thead><tr><th aria-label="播放"></th><th>歌曲</th><th>专辑</th>${source?'<th>来源</th>':''}<th>时长</th><th aria-label="操作"></th></tr></thead><tbody>${list.map((s,i)=>`<tr class="${s.id===state.current?'playing':''} ${playable(s)?'':'unavailable'}" data-song-row="${s.id}"><td><button class="row-play" data-play="${s.id}" ${context?`data-context="${esc(context)}"`:''} ${playable(s)?'':'disabled'} aria-label="播放 ${esc(s.title)}">${icon(s.id===state.current&&state.playing?'pause':'play')}</button></td><td class="title-cell">${esc(s.title)}<small><button class="text-link" data-route="artist:${esc(s.artist)}">${esc(s.artist)}</button></small></td><td class="muted"><button class="text-link" data-route="album:${esc(s.album)}">${esc(s.album)}</button></td>${source?`<td>${sourceTag(s)}</td>`:''}<td class="muted">${s.duration}</td><td><div class="row-actions"><button class="icon-button" data-add="${s.id}" aria-label="添加 ${esc(s.title)} 到当前播放的歌单">${icon('plus')}</button>${!s.local?`<button class="icon-button" data-download="${s.id}" aria-label="下载 ${esc(s.title)}" ${state.offline?'disabled':''}>${icon('download')}</button>`:''}<details class="row-menu"><summary aria-label="更多操作：${esc(s.title)}">${icon('more')}</summary><div>${button('下一首播放','play-next',`data-id="${s.id}"`)}${s.local?button('编辑歌曲信息…','edit-tags',`data-id="${s.id}"`):''}${context&&playlist(context)?button('从歌单移除','remove-entry',`data-id="${s.id}" data-playlist="${context}" ${playlist(context).scope==='remote'&&state.offline?'disabled':''}`):''}${library?button('从资料库删除文件…','delete-file',`data-id="${s.id}"`):''}</div></details>${state.editing&&context?`${button('↑','move-entry',`data-id="${s.id}" data-playlist="${context}" data-delta="-1" ${i===0?'disabled':''}`,'order-button')}${button('↓','move-entry',`data-id="${s.id}" data-playlist="${context}" data-delta="1" ${i===list.length-1?'disabled':''}`,'order-button')}`:''}</div></td></tr>`).join('')}</tbody></table></div>`;
}
function home(){const fresh=songs.filter(s=>s.fresh&&!s.local);const local=songs.filter(s=>s.local).sort((a,b)=>b.addedAt-a.addedAt);return heading('首页','新的发现，和已经留下的音乐。')+offlineBanner()+`<h2 class="section-title">为你推荐</h2><div class="resume-grid"><div class="radio-card"><span class="mini-cover">FM</span><div><h3>私人 FM</h3><p>根据你的聆听与收藏，接着发现。</p>${button(icon('play')+' 开始收听','fm',`data-kind="personal" ${state.offline||!state.loggedIn?'disabled':''}`)}</div></div><div class="radio-card"><span class="mini-cover">♡</span><div><h3>歌单电台</h3><label class="seed-label">基于 <select id="fm-seed" aria-label="歌单电台的推荐依据">${playlists.filter(p=>p.scope==='remote').map(p=>`<option value="${p.id}" ${state.fmSeed===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label>${button(icon('play')+' 心动模式','fm',`data-kind="playlist" ${state.offline||!state.loggedIn||!playlists.some(p=>p.scope==='remote')?'disabled':''}`)}</div></div></div>${!state.loggedIn?'<p class="subtitle">点击左下角头像连接账号，使用个性化推荐。</p>':''}<h2 class="section-title">关注艺人的新作<span class="section-hint">尚未收录到本地</span></h2><div class="card-grid">${fresh.slice(0,4).map((s,i)=>`<div class="discovery-card"><button class="music-card" data-route="artist:${esc(s.artist)}"><span class="cover ${['one','two','three','four'][i]}"><span class="cover-letter">${s.cover}</span><span class="play-corner">${icon('arrow')}</span></span><span class="card-title">${esc(s.album)}</span><span class="card-meta">${esc(s.artist)} · 新${i%2?'专辑':'单曲'}</span></button><div class="discovery-actions"><button class="icon-button" data-play="${s.id}" ${playable(s)?'':'disabled'} aria-label="播放 ${esc(s.title)}">${icon('play')}</button><button class="icon-button" data-add="${s.id}" aria-label="添加 ${esc(s.title)} 到当前播放的歌单">${icon('plus')}</button><button class="icon-button" data-download="${s.id}" ${state.offline?'disabled':''} aria-label="下载 ${esc(s.title)}">${icon('download')}</button></div></div>`).join('')||'<p class="subtitle">关注艺人的新作已全部收录。</p>'}</div><h2 class="section-title">最近存入本地<button data-route="songs">全部歌曲 ›</button></h2>${table(local.slice(0,5),{library:true})}`;}
function artistOrAlbum(name,isArtist){const key=isArtist?'artist':'album';const group=songs.filter(s=>s[key]===name);const local=group.filter(s=>s.local);const remote=group.filter(s=>!s.local);return heading(name,isArtist?'艺人':'专辑',isArtist?button('已关注','follow',`data-name="${esc(name)}"`):'')+offlineBanner()+`<h2 class="section-title">本地曲目</h2>${table(local,{library:true})}<h2 class="section-title">${isArtist?'热门歌曲':'网络曲目'}</h2>${table(remote,{source:true})}${isArtist?`<h2 class="section-title">最新推出的曲目／专辑</h2>${group.filter(s=>s.fresh).map(s=>`<div class="album-row"><span class="mini-cover">${s.cover}</span><div><h3><button class="text-link" data-route="album:${esc(s.album)}">${esc(s.album)}</button></h3><p>${esc(s.title)} · 新作</p></div><button class="icon-button" data-play="${s.id}" ${playable(s)?'':'disabled'} aria-label="播放 ${esc(s.title)}">${icon('play')}</button></div>`).join('')||'<p class="subtitle">暂无新作。</p>'}`:''}`;}
function renderContent(){const el=document.querySelector('#content');if(!el)return;let html='';const local=songs.filter(s=>s.local);
 if(state.query.trim()){const q=state.query.trim().toLowerCase();const matches=songs.filter(s=>`${s.title} ${s.artist} ${s.album}`.toLowerCase().includes(q)).sort((a,b)=>Number(b.local)-Number(a.local));html=heading('搜索',`“${esc(state.query.trim())}” · 同时搜索本地与网络，同一首歌优先播放本地版本。`)+offlineBanner()+table(matches,{source:true});}
 else if(state.route==='home')html=home();
 else if(state.route==='songs')html=heading('歌曲',`${local.length} 首本地歌曲`)+table(local,{library:true});
 else if(state.route==='artists'||state.route==='albums'){const artist=state.route==='artists';const groups=[...new Set(local.map(s=>artist?s.artist:s.album))];html=heading(title(),artist?'本地资料库中的艺人':'本地资料库中的专辑')+groups.map(name=>{const list=local.filter(s=>(artist?s.artist:s.album)===name);return `<div class="album-row"><button class="mini-cover group-link" data-route="${artist?'artist':'album'}:${esc(name)}" aria-label="打开 ${esc(name)}">${artist?icon('artists'):list[0].cover}</button><button class="group-heading text-link" data-route="${artist?'artist':'album'}:${esc(name)}"><h3>${esc(name)}</h3><p>${list.length} 首本地曲目</p></button><button class="icon-button" data-route="${artist?'artist':'album'}:${esc(name)}" aria-label="打开 ${esc(name)}">${icon('arrow')}</button></div>`;}).join('');}
 else if(state.route.startsWith('artist:'))html=artistOrAlbum(state.route.slice(7),true);
 else if(state.route.startsWith('album:'))html=artistOrAlbum(state.route.slice(6),false);
 else if(state.route.startsWith('playlist:')){const p=playlist(state.route.slice(9));if(!p){navigate('home');return;}const remote=p.scope==='remote';const canEdit=!remote||(!state.offline&&state.loggedIn);html=heading(p.name,`${p.ids.length} 首歌曲${p.description?` · ${esc(p.description)}`:''}`,button(icon('play')+' 播放','play-playlist',`data-playlist="${p.id}" ${!p.ids.some(id=>playable(song(id)))?'disabled':''}`,'primary')+button('编辑歌单…','edit-playlist',`data-playlist="${p.id}" ${canEdit?'':'disabled'}`)+(remote?'':button('歌单文件…','playlist-file',`data-playlist="${p.id}"`)),remote?'远程歌单':'本地歌单')+(remote?offlineBanner():'')+`<div class="playlist-tools">${button(state.editing?'完成排序':'调整顺序','toggle-editing',canEdit?'':'disabled')}${button('删除歌单…','delete-playlist',`data-playlist="${p.id}" ${canEdit?'':'disabled'}`,'text-link')}</div>`+table(p.ids.map(song).filter(Boolean),{source:remote,context:p.id});}
 else if(state.route==='downloads')html=heading(downloadTitle(),'本次下载任务。完成的歌曲已保存到本地资料库。',button('清除已完成','clear-downloads'))+offlineBanner()+`<div class="download-list">${state.downloads.map(t=>`<div class="download-row"><span class="mini-cover">${song(t.songId).cover}</span><div><strong>${esc(song(t.songId).title)}</strong><p>${t.status==='done'?'已完成':t.status==='failed'?'下载失败 · 待处理':state.offline?'等待恢复网络':`正在下载 · ${t.progress}%`}${t.targets.length?' · 完成后加入 '+t.targets.map(id=>esc(playlist(id)?.name||'歌单')).join('、'):''}</p>${t.status==='running'?`<progress max="100" value="${t.progress}"></progress>`:''}</div>${t.status==='failed'?button('重试','retry-download',`data-id="${t.songId}" ${state.offline?'disabled':''}`):icon(t.status==='done'?'check':'download')}</div>`).join('')}</div>`;
 else if(state.route==='settings')html=heading('设置','外观跟随系统；本地音乐始终独立可用。')+`<section class="settings-section"><h2>自动保存本地</h2><label class="setting-line"><span><strong>经常听的音乐自动保存</strong><small>一首歌曲完整在线播放达到指定次数后，保存音频到本地。</small></span><input id="auto-save" type="checkbox" ${state.settings.autoSave?'checked':''}></label><label class="setting-line"><span>完整播放次数</span><input id="auto-threshold" type="number" min="1" max="100" value="${state.settings.threshold}" ${state.settings.autoSave?'':'disabled'}></label><p class="subtitle">暂停、跳过、拖到结尾均不计数；本地播放不累计。</p></section><section class="settings-section"><h2>侧边栏</h2><label class="setting-line"><span>显示远程歌单</span><input id="show-remote" type="checkbox" ${state.settings.showRemote?'checked':''}></label></section><section class="settings-section"><h2>歌曲信息</h2><p class="subtitle">优先使用文件内的标题、艺人、专辑与封面。联网匹配先预览，再写入音频标签；只补空缺，不自动覆盖手工编辑。</p></section>`;
 el.innerHTML=html;
}
function queueView(){return `<aside class="queue" aria-label="当前播放列表"><div class="queue-heading"><h2>${esc(state.queueTitle)}</h2>${button(icon('close'),'queue',`aria-label="关闭播放列表"`,'icon-button')}</div><p>${state.activePlaylist?'正在播放的歌单':'临时播放列表'} · ${state.queue.length} 首</p>${!state.activePlaylist?button(icon('plus')+' 保存为歌单','save-queue','','save-queue'):''}${state.queue.map(id=>{const s=song(id);return `<div class="queue-item"><span class="mini-cover">${s.cover}</span><button data-queue-play="${id}" ${playable(s)?'':'disabled'}>${esc(s.title)}<small>${esc(s.artist)} · ${s.local?'本地':'网络'}</small></button><button class="icon-button" data-dequeue="${id}" aria-label="从播放列表移除 ${esc(s.title)}">${icon('close')}</button></div>`;}).join('')}</aside>`;}
function renderPlayer(){const s=song(state.current);const el=document.querySelector('#player');if(!el)return;el.innerHTML=`<div class="now-playing"><span class="mini-cover">${s?.cover||'♪'}</span><div><strong>${esc(s?.title||'尚未播放')}</strong><small>${esc(s?.artist||'选择一首歌曲')}</small><small id="playback-source">${state.playbackSource==='local'?'本地':'网络'}</small></div></div><div class="transport"><div class="transport-buttons">${button(icon('shuffle'),'shuffle',`aria-label="随机播放" aria-pressed="${state.shuffle}"`,'icon-button '+(state.shuffle?'selected':''))}${button(icon('previous'),'previous','aria-label="上一首"','icon-button')}${button(icon(state.playing?'pause':'play'),'toggle-play',`aria-label="${state.playing?'暂停':'播放'}"`,'icon-button main-play')}${button(icon('next'),'next','aria-label="下一首"','icon-button')}${button(icon('repeat'),'repeat',`aria-label="循环播放" aria-pressed="${state.repeat}"`,'icon-button '+(state.repeat?'selected':''))}</div><label class="seek"><span>0:00</span><input id="progress" type="range" min="0" max="100" value="${state.progress}" aria-label="播放进度"><span>${s?.duration||'0:00'}</span></label></div><div class="player-right">${icon('volume')}<input id="volume" type="range" min="0" max="100" value="${state.volume}" aria-label="音量">${button(icon('queue'),'queue',`aria-label="当前播放列表" aria-expanded="${state.queueOpen}"`,'icon-button '+(state.queueOpen?'selected':''))}</div>`;}
function startPlayback(id,{ids,playlistId=null,name='临时播放列表',keepQueue=false}={}){const s=song(id);if(!playable(s)){notify('当前离线，请选择本地歌曲。');return;}if(!keepQueue){state.queue=ids||[id];state.activePlaylist=playlistId;state.queueTitle=name;}state.current=id;state.playing=true;state.playbackSource=s.local?'local':'network';state.progress=0;state.seeked=false;state.run++;shell();}
function playPlaylist(p){startPlayback(p.ids.find(id=>playable(song(id))),{ids:[...p.ids],playlistId:p.id,name:p.name});}
function step(delta,automatic=false){const ids=state.queue.filter(id=>playable(song(id)));if(!ids.length){state.playing=false;renderPlayer();return;}const i=ids.indexOf(state.current);let next=i+delta;if(state.shuffle&&ids.length>1)next=(Math.max(i,0)+1+Math.floor(Math.random()*(ids.length-1)))%ids.length;else if(next<0||next>=ids.length){if(state.repeat)next=(next+ids.length)%ids.length;else{if(!automatic)notify('已到播放列表边界。');state.playing=false;renderPlayer();updateSimulation();return;}}startPlayback(ids[next],{keepQueue:true});}
function updateSimulation(){const s=song(state.current);document.querySelector('#simulate-ended').disabled=!state.playing;document.querySelector('#simulate-failure').disabled=!state.downloads.some(t=>t.status==='running');document.querySelector('#simulation-status').textContent=s?`${s.title} · 完整在线播放 ${s.listenCount} 次`:'';}
function completePlayback(){if(!state.playing||state.countedRun===state.run)return;state.countedRun=state.run;const s=song(state.current);if(state.playbackSource==='network'&&!state.seeked){s.listenCount++;if(state.settings.autoSave&&!s.local&&s.listenCount>=state.settings.threshold)startDownload(s.id,'auto');else notify(`“${s.title}”完整在线播放 ${s.listenCount} 次。`);}else if(state.seeked){notify('本次播放有拖动进度，不计入完整播放次数。');}state.playing=false;state.progress=100;persist();step(1,true);renderContent();updateSimulation();}
function syncActive(p){if(state.activePlaylist===p.id){state.queue=[...p.ids];state.queueTitle=p.name;}}
function addToPlaylist(s,p){if(p.scope==='local'&&!s.local)return false;if(p.scope==='remote'&&(!state.loggedIn||state.offline)){notify('编辑远程歌单需要联网并连接账号。');return false;}if(p.ids.includes(s.id))return false;p.ids.push(s.id);syncActive(p);persist();return true;}
function feedback(text){const el=document.querySelector('#add-feedback');el.hidden=false;el.innerHTML=`<span>${esc(text)}</span>${button('更改…','change-add')}${button(icon('close'),'dismiss-add','aria-label="关闭添加提示"','icon-button')}`;}
function addSong(id,target=state.activePlaylist){const s=song(id);const p=playlist(target);state.addIntent={songId:id,target:target||null,inserted:false};if(p?.scope==='remote'&&(state.offline||!state.loggedIn)){feedback('远程歌单暂不可修改，可更改为本地歌单或临时播放列表。');return;}if(p&&p.scope==='local'&&!s.local){if(state.offline){feedback(`“${s.title}”需下载后才能加入「${p.name}」`);notify('当前离线，恢复联网后再添加。');return;}startDownload(id,'manual',p.id);feedback(`下载完成后加入「${p.name}」`);}else if(p){state.addIntent.inserted=addToPlaylist(s,p);feedback(`已${state.addIntent.inserted?'加入':'在'}「${p.name}」`);}else{state.addIntent.inserted=!state.queue.includes(id);if(state.addIntent.inserted)state.queue.push(id);feedback('已加入当前临时播放列表');}shell();}
function startDownload(id,origin='manual',target=null){const s=song(id);if(s.local){if(target)addToPlaylist(s,playlist(target));return;}if(state.offline){notify('当前离线，恢复联网后可下载。');return;}let t=state.downloads.find(t=>t.songId===id&&t.status!=='done');if(!t){t={songId:id,origin,status:'running',progress:0,targets:[],keepFile:!target};state.downloads.push(t);}if(!target)t.keepFile=true;if(target&&!t.targets.includes(target))t.targets.push(target);if(t.status==='failed')t.status='running';persist();shell();}
setInterval(()=>{let changed=false;for(const t of state.downloads){if(t.status!=='running'||state.offline)continue;t.progress=Math.min(100,t.progress+20);changed=true;if(t.progress===100){t.status='done';const s=song(t.songId);s.local=true;s.origin=t.origin;s.addedAt=Date.now();for(const id of t.targets){const p=playlist(id);if(p){const inserted=addToPlaylist(s,p);if(state.addIntent?.songId===s.id&&state.addIntent.target===id)state.addIntent.inserted=inserted;}}notify(`“${s.title}”已保存到本地${t.targets.length?'并加入歌单':''}。`);}}if(changed){persist();shell();}},550);
function dialog(title,body,actions){const d=document.querySelector('#action-dialog');d.innerHTML=`<h2 id="dialog-title">${esc(title)}</h2>${body}<div class="dialog-actions">${button('取消','close-dialog')}${actions}</div>`;if(!d.open)d.showModal();d.querySelector('input,select,textarea,button')?.focus();}
function closeDialog(){document.querySelector('#action-dialog').close();state.metadataCandidate=null;}
function playlistDialog(p=null,{scope='local',fromQueue=false,addAfter=false}={}){dialog(p?'编辑歌单':fromQueue?'保存当前播放列表':'新建歌单',`<form id="playlist-form"><label class="form-field">名称<input name="name" required maxlength="80" value="${esc(p?.name||'')}" placeholder="歌单名称"></label><label class="form-field">描述<input name="description" maxlength="200" value="${esc(p?.description||'')}"></label>${!p?`<label class="form-field">保存到<select name="scope"><option value="local" ${scope==='local'?'selected':''}>本地 · M3U8 文件</option><option value="remote" ${scope==='remote'?'selected':''} ${state.offline||!state.loggedIn?'disabled':''}>远程 · 网易云音乐</option></select></label><p class="subtitle">${fromQueue?'保存到本地时，网络曲目先下载，成功后入单。':'本地歌单中的曲目均保存于本地。'}</p>`:''}</form>`,button(p?'保存修改':'创建并保存','submit-playlist',`${p?`data-playlist="${p.id}"`:''} data-queue="${fromQueue}" data-add-after="${addAfter}" type="submit" form="playlist-form"`,'primary'));}
function addPicker(){const intent=state.addIntent;if(!intent)return;dialog('添加到其他歌单',`<p>为“${esc(song(intent.songId).title)}”选择目标。默认添加可在这里改到另一张歌单。</p><div class="target-list">${playlists.map(p=>button(`${p.scope==='local'?'本地':'远程'} · ${esc(p.name)}${p.id===intent.target?' ✓':''}`,'pick-target',`data-playlist="${p.id}" ${p.scope==='remote'&&(state.offline||!state.loggedIn)?'disabled':''}`)).join('')}${button('当前临时播放列表','pick-target','data-playlist="queue"')}</div>`,button('新建歌单…','create-playlist','data-scope="local" data-add-after="true"'));}
function changeTarget(target){const old=state.addIntent;if(!old)return;const s=song(old.songId);if(target==='queue')target=null;if(old.target===target){closeDialog();return;}const next=playlist(target);if(next?.scope==='remote'&&(state.offline||!state.loggedIn))return;if(next?.scope==='local'&&!s.local&&state.offline){notify('当前离线，无法先下载到本地。');return;}if(old.inserted){const p=playlist(old.target);if(p){p.ids=p.ids.filter(id=>id!==s.id);syncActive(p);}else state.queue=state.queue.filter(id=>id!==s.id);}for(const t of state.downloads)t.targets=t.targets.filter(id=>id!==old.target||t.songId!==s.id);if(next?.scope!=='local')state.downloads=state.downloads.filter(t=>t.songId!==s.id||t.status==='done'||t.keepFile||t.targets.length);persist();closeDialog();addSong(s.id,target);}
function m3u(p){return '#EXTM3U\n'+p.ids.map(id=>{const s=song(id);const [m,sec]=s.duration.split(':').map(Number);return `#EXTINF:${m*60+sec},${s.artist.replace(/[\r\n]/g,' ')} - ${s.title.replace(/[\r\n]/g,' ')}\n${s.filePath}`;}).join('\n')+'\n';}
function tagsDialog(id){const s=song(id);dialog('歌曲信息',`<p>示例编辑：正式版写入音频文件标签，不只保存在 App 里。</p><form id="tags-form"><label class="form-field">标题<input name="title" required value="${esc(s.title)}"></label><label class="form-field">艺人<input name="artist" required value="${esc(s.artist)}"></label><label class="form-field">专辑<input name="album" required value="${esc(s.album)}"></label><label class="form-field">专辑艺人<input name="albumArtist" value="${esc(s.albumArtist||'')}"></label><label class="form-field">流派<input name="genre" value="${esc(s.genre||'')}"></label></form><p class="subtitle">联网匹配：已有网易 ID 优先；其他文件使用 MusicBrainz，必要时用 AcoustID 音频指纹。候选结果先预览。</p><div id="metadata-preview"></div>`,button('匹配信息示例…','match-tags',`data-id="${id}" ${state.offline?'disabled':''}`)+button('保存到文件','save-tags',`data-id="${id}" type="submit" form="tags-form"`,'primary'));}
function deleteFile(id){const s=song(id);const refs=playlists.filter(p=>p.scope==='local'&&p.ids.includes(id));dialog('从资料库删除文件？',`<p>“${esc(s.title)}”的音频文件将移到废纸篓，并从资料库${refs.length?'及 '+refs.length+' 张本地歌单':''}中移除。远程歌单保留这首歌的网络条目。</p><p>此处仅演示，不会删除任何真实文件。</p>`,button('移到废纸篓','confirm-delete-file',`data-id="${id}"`,'danger'));}
function refreshViews(){persist();shell();}
document.addEventListener('click',event=>{
 const b=event.target.closest('button');if(!b||b.disabled)return;if(b.type==='submit')event.preventDefault();
 if(b.dataset.route){navigate(b.dataset.route);return;}
 if(b.dataset.play){const id=Number(b.dataset.play);const p=playlist(b.dataset.context);if(p){startPlayback(id,{ids:[...p.ids],playlistId:p.id,name:p.name});}else{const ids=[...new Set([...document.querySelectorAll('#content [data-song-row]')].map(e=>Number(e.dataset.songRow)))];startPlayback(id,{ids:ids.includes(id)?ids:[id],name:state.query?'搜索结果':state.route.startsWith('artist:')?state.route.slice(7):'发现音乐'});}return;}
 if(b.dataset.queuePlay){startPlayback(Number(b.dataset.queuePlay),{keepQueue:true});return;}
 if(b.dataset.add){addSong(Number(b.dataset.add));return;}
 if(b.dataset.download){startDownload(Number(b.dataset.download));return;}
 if(b.dataset.dequeue){const id=Number(b.dataset.dequeue);state.queue=state.queue.filter(x=>x!==id);shell();return;}
 const id=Number(b.dataset.id);const s=song(id);const p=playlist(b.dataset.playlist);
 switch(b.dataset.action){
 case 'account':state.accountOpen=!state.accountOpen;shell();break;
 case 'account-close':state.accountOpen=false;shell();break;
 case 'settings':navigate('settings');break;
 case 'login':if(!state.offline){state.loggedIn=!state.loggedIn;state.accountOpen=false;shell();notify(state.loggedIn?'已模拟连接账号，显示示例头像和用户名。':'已退出示例账号，本地资料库保留。');}break;
 case 'queue':state.queueOpen=!state.queueOpen;shell();break;
 case 'toggle-play':if(state.playing){state.playing=false;renderPlayer();renderContent();updateSimulation();}else if(state.current&&state.progress<100&&state.run>0&&playable(song(state.current))){state.playing=true;renderPlayer();renderContent();updateSimulation();}else if(state.current)startPlayback(state.current,{keepQueue:true});break;
 case 'next':step(1);break;case 'previous':step(-1);break;
 case 'shuffle':state.shuffle=!state.shuffle;renderPlayer();break;case 'repeat':state.repeat=!state.repeat;renderPlayer();break;
 case 'fm':if(!state.offline&&state.loggedIn){const personal=b.dataset.kind==='personal';startPlayback(personal?10:4,{ids:personal?[10,11,4,7]:[4,9,1,12],name:personal?'私人 FM':`歌单电台 · ${playlist(state.fmSeed)?.name||'我的收藏'}`});state.queueOpen=true;shell();}break;
 case 'follow':notify('示例：这里管理关注状态；正式版同步网易云关注艺人。');break;
 case 'play-playlist':if(p)playPlaylist(p);break;
 case 'play-next':{const i=state.queue.indexOf(state.current);state.queue=state.queue.filter(x=>x!==id);state.queue.splice(Math.max(0,i+1),0,id);shell();notify('已安排下一首播放。');break;}
 case 'change-add':addPicker();break;case 'dismiss-add':document.querySelector('#add-feedback').hidden=true;break;
 case 'pick-target':changeTarget(b.dataset.playlist);break;
 case 'close-dialog':closeDialog();break;
 case 'create-playlist':playlistDialog(null,{scope:b.dataset.scope||'local',addAfter:b.dataset.addAfter==='true'});break;
 case 'save-queue':playlistDialog(null,{fromQueue:true});break;
 case 'edit-playlist':if(p&&!(p.scope==='remote'&&(state.offline||!state.loggedIn)))playlistDialog(p);break;
 case 'submit-playlist':{
  const form=document.querySelector('#playlist-form');if(!form.reportValidity())return;const data=new FormData(form);const name=String(data.get('name')).trim();if(!name){form.elements.name.setCustomValidity('请输入歌单名称');form.reportValidity();return;}
  if(p){p.name=name;p.description=String(data.get('description')).trim();syncActive(p);closeDialog();refreshViews();break;}
  const scope=data.get('scope');if(scope==='remote'&&(state.offline||!state.loggedIn))return;
  const created={id:'p-'+Date.now(),name,description:String(data.get('description')).trim(),scope,ids:[]};playlists.push(created);
  const fromQueue=b.dataset.queue==='true';const addAfter=b.dataset.addAfter==='true';const pending=[];
  if(fromQueue){for(const trackId of state.queue){if(scope==='local'&&!song(trackId).local)pending.push(trackId);else created.ids.push(trackId);}if(!pending.length){state.activePlaylist=created.id;state.queueTitle=created.name;}}
  closeDialog();navigate(`playlist:${created.id}`);for(const trackId of pending)startDownload(trackId,'manual',created.id);
  if(addAfter&&state.addIntent)changeTarget(created.id);
  refreshViews();notify(pending.length?`“${name}”已创建，${pending.length} 首网络歌曲下载成功后加入。`:`“${name}”已保存。`);break;
 }
 case 'toggle-editing':state.editing=!state.editing;renderContent();break;
 case 'move-entry':if(p&&!(p.scope==='remote'&&state.offline)){const index=p.ids.indexOf(id);const next=index+Number(b.dataset.delta);if(index>=0&&next>=0&&next<p.ids.length){[p.ids[index],p.ids[next]]=[p.ids[next],p.ids[index]];syncActive(p);refreshViews();}}break;
 case 'remove-entry':if(p&&!(p.scope==='remote'&&(state.offline||!state.loggedIn))){p.ids=p.ids.filter(x=>x!==id);syncActive(p);refreshViews();notify('已从歌单移除，音频文件保留。');}break;
 case 'delete-playlist':if(p)dialog('删除这张歌单？',`<p>删除“${esc(p.name)}”${p.scope==='local'?'及其 M3U8 歌单文件':''}，保留所有音频文件。</p>`,button('删除歌单','confirm-delete-playlist',`data-playlist="${p.id}"`,'danger'));break;
 case 'confirm-delete-playlist':if(p){playlists.splice(playlists.indexOf(p),1);for(const t of state.downloads)t.targets=t.targets.filter(x=>x!==p.id);if(state.activePlaylist===p.id){state.activePlaylist=null;state.queueTitle='临时播放列表';}closeDialog();navigate('home');persist();notify('歌单已删除，音频文件保留。');}break;
 case 'playlist-file':if(p)dialog('M3U8 歌单文件',`<p>${esc(p.name)}.m3u8 · UTF-8<br>正式版随歌单编辑自动保存；其他播放器可读取同一文件。音频标签保存完整元信息，歌单保存顺序与路径。</p><textarea class="m3u-preview" readonly aria-label="M3U8 内容">${esc(m3u(p))}</textarea><p class="subtitle">以下均为示例路径，导出文件仅用于查看格式。</p>`,button('导出示例文件','export-file',`data-playlist="${p.id}"`));break;
 case 'export-file':if(p){const link=document.createElement('a');const blob=URL.createObjectURL(new Blob([m3u(p)],{type:'audio/x-mpegurl;charset=utf-8'}));link.href=blob;link.download=p.name+'.m3u8';link.click();setTimeout(()=>URL.revokeObjectURL(blob),1000);notify('已导出示例 M3U8；其中路径不对应真实文件。');}break;
 case 'clear-downloads':state.downloads=state.downloads.filter(t=>t.status!=='done');refreshViews();break;
 case 'retry-download':startDownload(id,'manual');break;
 case 'edit-tags':if(s?.local)tagsDialog(id);break;
 case 'match-tags':state.metadataCandidate={albumArtist:s.artist,genre:'独立音乐'};document.querySelector('#metadata-preview').innerHTML=`<div class="metadata-proposal"><strong>匹配结果预览 · 示例</strong><p>来源：MusicBrainz 候选示例<br>专辑艺人：${esc(s.artist)}<br>流派：独立音乐<br>已有的标题、艺人、专辑保持不变。</p>${button('采用这组补充信息','apply-match')}</div>`;break;
 case 'apply-match':if(state.metadataCandidate){const f=document.querySelector('#tags-form');for(const [key,value]of Object.entries(state.metadataCandidate))if(f.elements[key]&&!f.elements[key].value)f.elements[key].value=value;notify('已填入空缺字段，点击保存后才写入文件（示例）。');}break;
 case 'save-tags':{const f=document.querySelector('#tags-form');if(!f.reportValidity())return;const data=new FormData(f);for(const key of ['title','artist','album']){if(!String(data.get(key)||'').trim()){f.elements[key].setCustomValidity('请输入有效内容');f.reportValidity();return;}}for(const key of ['title','artist','album','albumArtist','genre'])s[key]=String(data.get(key)||'').trim();closeDialog();refreshViews();notify('示例歌曲信息已更新；正式版会写入音频标签并同步歌单显示。');break;}
 case 'delete-file':if(s?.local)deleteFile(id);break;
 case 'confirm-delete-file':if(s){s.local=false;s.origin=null;for(const list of playlists.filter(p=>p.scope==='local'))list.ids=list.ids.filter(x=>x!==id);state.queue=state.queue.filter(x=>x!==id);state.downloads=state.downloads.filter(t=>t.songId!==id);if(state.current===id){state.playing=false;state.current=state.queue[0]||null;state.playbackSource=song(state.current)?.local?'local':'network';}closeDialog();refreshViews();notify('已模拟删除音频文件，并清理资料库及本地歌单引用。');}break;
 }
});
document.addEventListener('input',event=>{const el=event.target;if(el.id==='global-search'){state.query=el.value;state.accountOpen=false;renderContent();}else if(el.id==='progress'){state.progress=Number(el.value);state.seeked=true;/* Seeking never completes a listen. */}else if(el.id==='volume')state.volume=Number(el.value);else if(el instanceof HTMLInputElement&&el.form)el.setCustomValidity('');});
document.addEventListener('change',event=>{const el=event.target;if(el.id==='auto-save'){state.settings.autoSave=el.checked;persist();renderContent();}else if(el.id==='auto-threshold'){const n=Number(el.value);if(!Number.isInteger(n)||n<1||n>100){el.value=state.settings.threshold;notify('播放次数请输入 1–100 的整数。');return;}state.settings.threshold=n;persist();}else if(el.id==='show-remote'){state.settings.showRemote=el.checked;refreshViews();}else if(el.id==='fm-seed')state.fmSeed=el.value;});
document.querySelector('#offline').addEventListener('change',event=>{state.offline=event.target.checked;if(state.offline&&state.playing&&state.playbackSource==='network'){state.playing=false;notify('已模拟断网，网络播放暂停。本地歌曲照常使用。');}shell();});
document.querySelector('#appearance').addEventListener('change',event=>{if(event.target.value==='system')delete document.documentElement.dataset.appearance;else document.documentElement.dataset.appearance=event.target.value;});
document.querySelector('#notes-button').addEventListener('click',()=>{const e=document.querySelector('#design-notes');e.hidden=!e.hidden;document.querySelector('#notes-button').setAttribute('aria-expanded',String(!e.hidden));if(!e.hidden)e.scrollIntoView({behavior:'smooth',block:'nearest'});});
document.querySelector('#simulate-ended').addEventListener('click',completePlayback);
document.querySelector('#simulate-failure').addEventListener('click',()=>{const t=state.downloads.find(t=>t.status==='running');if(t){t.status='failed';persist();shell();notify('已模拟下载失败。目标歌单尚未加入曲目，可在下载页重试。');}});
document.querySelector('#simulate-restart').addEventListener('click',()=>location.reload());
document.querySelector('#reset-demo').addEventListener('click',()=>{try{localStorage.removeItem(STORAGE);}catch{}location.reload();});
shell();

document.addEventListener('submit',event=>event.preventDefault());
document.querySelector('#action-dialog').addEventListener('close',()=>{state.metadataCandidate=null;});
